"""Keep pydantic working on CPython 3.14.0rc2.

Pydantic 2.13 calls typing._eval_type(prefer_fwd_module=True). That keyword
existed in early 3.14 builds and was removed in 3.14.0rc2, so importing the
OpenAI client crashes. Drop the argument when this interpreter does not accept it.
"""
import inspect
import typing

_original_eval_type = typing._eval_type
_accepts_prefer_fwd_module = "prefer_fwd_module" in inspect.signature(_original_eval_type).parameters


def _eval_type(*args, **kwargs):
    if not _accepts_prefer_fwd_module:
        kwargs.pop("prefer_fwd_module", None)
    return _original_eval_type(*args, **kwargs)


typing._eval_type = _eval_type
